import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        // The reward telescopes to end - start; low[r][c] = min value of any cell that can reach (r, c), itself included.
        int[][] low = new int[n][m];
        long ans = Long.MIN_VALUE;
        for (int r = 0; r < n; r++)
            for (int c = 0; c < m; c++) {
                int a = nextInt();
                if (r == 0 && c == 0) {
                    low[r][c] = a;
                    continue;
                }
                int best = Integer.MAX_VALUE;
                if (r > 0) best = Math.min(best, low[r - 1][c]);
                if (c > 0) best = Math.min(best, low[r][c - 1]);
                ans = Math.max(ans, (long) a - best);
                low[r][c] = Math.min(a, best);
            }
        System.out.println(ans);
    }
}

package main

import (
	"fmt"
	"io"
	"math"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), int(nextInt())
	// The reward telescopes to end - start; low[r][c] = min value of any cell that can reach (r, c), itself included.
	low := make([][]int64, n)
	ans := int64(math.MinInt64)
	for r := 0; r < n; r++ {
		low[r] = make([]int64, m)
		for c := 0; c < m; c++ {
			a := nextInt()
			if r == 0 && c == 0 {
				low[r][c] = a
				continue
			}
			best := int64(math.MaxInt64)
			if r > 0 {
				best = min(best, low[r-1][c])
			}
			if c > 0 {
				best = min(best, low[r][c-1])
			}
			ans = max(ans, a-best)
			low[r][c] = min(a, best)
		}
	}
	fmt.Println(ans)
}
